ActionExecuteScript.Script:
using System;
using System.Linq;
using Triggernometry.Core.Scripting;
using Triggernometry.Expressions.Maths;
using Triggernometry.Expressions.String.Utils;
using Triggernometry.FFXIV;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;

// 0x123, 0x456, ...
var data = ScriptHelper.GetRegisteredVariable("bby._彩蛋技能IDs") ?? "";

var candidates = ArgHelper.SplitArguments(data)
    .Select(part => (uint)MathParser.Parse(part))
    .ToArray();
if (candidates.Length > 0)
{
    var abilityId = candidates[new Random().Next(candidates.Length)];

    var m = new ActorControlModule();
    m.Scan();
    m.BlueActionLearn(abilityId);
}

public class ActorControlModule : ModuleBase
{
    public IntPtr HandleActorControlFuncPtr { get; set; }

    public ActorControlModule()
    {
        ScanMethod = () =>
        {
            HandleActorControlFuncPtr = Scanner.TryScanMultiple(new string[] {
                "44 8B 4F ? 44 8B 47 ? 89 44 24 ? 8B 47 ? 89 44 24 ? E8 * * * *",
                "40 55 53 57 41 54 41 56 48 8D AC 24 ? ? ? ? B8 ? ? ? ?"
            }, nameof(HandleActorControlFuncPtr));
        };
    }

    public void BlueActionLearn(uint abilityId)
    {
        var myId = Entity.GetMyself().ID;
        ushort category = 0x63;
        ActorControl(myId, category, abilityId, 1);
    }

    public void ActorControl(uint objectId, ushort category, uint a1 = 0, uint a2 = 0, uint a3 = 0, uint a4 = 0)
        => HandleActorControl(objectId, category, a1, a2, a3, a4, 0, 0, 0, 0, 0xE0000000, 0);

    public void HandleActorControl(uint objectId, ushort category, uint a1, uint a2, uint a3, uint a4, uint a5, uint a6, uint a7, uint a8, uint targetId, uint unk)
    {
        if (HandleActorControlFuncPtr == IntPtr.Zero)
            return;
        _ = Plugin.Call<IntPtr>(HandleActorControlFuncPtr, objectId, category, a1, a2, a3, a4, a5, a6, a7, a8, targetId, unk);
    }
}

